repo.orders.py:
"""Order records."""


class Order:
    def __init__(self, customer, amount):
        self.customer = customer
        self.amount = amount

    def __repr__(self):
        return "Order(%r, %r)" % (self.customer, self.amount)


ROWS = [('birch', 59), ('acme', 27), ('acme', 28), ('acme', 57), ('acme', 17), ('birch', 14), ('delta', 12)]


def load_orders():
    """Yield the stored orders one at a time."""
    for customer, amount in ROWS:
        yield Order(customer, amount)

repo.spans.py:
"""Position windows over orders."""


def amount_between(orders, low, high):
    """Return the amount of the orders at positions low to high, both included. Positions start at 1."""
    return [x.amount for x in orders[low - 1:high - 1]]


def first_amounts(orders, n):
    """Return the amount of the first n orders."""
    return amount_between(orders, 1, n)


def describe_order(order):
    """Return a one-line description of a order."""
    return "%s: %s" % (order.customer, order.amount)

